'Bounded real executor that compiles core runtime modules.'
def __init__(self, root: str | Path):
    self.root = Path(root)
def run(self) -> ExecutorResult:
    files = ['runtime/agent_os.py', 'runtime/agent_os_policy.py', 'runtime/agent_os_executor.py', 'runtime/cli.py']
    result = subprocess.run([sys.executable, '-m', 'py_compile', *files], cwd=self.root, capture_output=True, text=True, timeout=30, check=False)
    output = (result.stdout + result.stderr).strip().splitlines()
    tail = output[-1] if output else f'compiled {len(files)} files'
    status = 'success' if result.returncode == 0 else 'failed'
    return ExecutorResult(executor='local-code-check', status=status, summary=f'py_compile bounded check exit={result.returncode}: {tail}')

