def generate_variants(self, command: str, max_variants: int) -> List[Dict]:
    variants = []
    for name, pattern, replacement in VARIANT_TEMPLATES:
    m = pattern.match(command)
    if m:
        if callable(replacement):
            candidates = replacement(m)
        else:
            candidates = replacement
        for c in candidates:
            if c != command:
                variants.append({'command': c, 'template': name, 'base': command})
        break
    return variants[:max_variants]

