def classify_error(stderr: str, exit_code: int, command: str) -> str:
    """从 stderr + exit_code 分类错误类型。"""
    if not stderr:
        if exit_code == 127: return "not_found"
        if exit_code == 126: return "permission_error"
        if exit_code < 0: return "signal"
        return "unknown"

    s = stderr.lower()

    if "syntaxerror" in s or "syntax error" in s or "indentationerror" in s:
        return "syntax_error"
    if "failed" in s and ("test" in s or "pytest" in command):
        return "test_failure"
    if "assert" in s or "assertionerror" in s:
        return "test_failure"
    if "error" in s and "passed" in s:
        return "test_failure"
    if "importerror" in s or "modulenotfounderror" in s or "no module named" in s:
        return "import_error"
    if "permission denied" in s or "access denied" in s:
        return "permission_error"
    if "timeout" in s or "timed out" in s:
        return "timeout"
    if "no such file" in s or "file not found" in s or "does not exist" in s:
        return "not_found"
    if "not a git repository" in s:
        return "not_found"
    if "did not match" in s or "pathspec" in s:
        return "not_found"
    return "unknown"
