'\n    Analyzes LLM output and decides what to do next.\n    Maps function calls to real tool executions.\n    '
def __init__(self, executor, config):
    self.executor = executor
    self.config = config
def _check_command_safety(self, command: str) -> Dict[str, Any]:
    """Check if a bash command is safe to execute.

        Returns:
            {"allowed": bool, "reason": str, "requires_confirmation": bool}
        """
    cmd_lower = command.strip().lower()
    if self.config.allowed_commands:
        if not any((cmd_lower.startswith(ac.lower()) for ac in self.config.allowed_commands)):
            return {'allowed': False, 'reason': f'Command not in allowlist: {command[:80]}', 'requires_confirmation': False}
    for blocked in self.config.blocked_commands:
        if blocked.lower() in cmd_lower:
            return {'allowed': False, 'reason': f"Dangerous command blocked: matches pattern '{blocked}'", 'requires_confirmation': True}
    dangerous_patterns = ['rm -rf', 'rmdir /s', 'del /f /s /q', '> /dev/', 'mkfs', 'fdisk', 'chmod 777', 'chown root', 'curl | bash', 'wget | bash', 'curl|bash', 'wget|bash', 'eval(', 'exec(']
    for pattern in dangerous_patterns:
        if pattern in cmd_lower:
            return {'allowed': False, 'reason': f"Potentially dangerous command: contains '{pattern}'", 'requires_confirmation': True}
    return {'allowed': True, 'reason': 'Command passed safety check', 'requires_confirmation': False}
def _collect_function_calls(self, output_items: List[Dict]) -> List:
    """Extract function_call items as (call_id, name, args) tuples."""
    calls = []
    for item in output_items:
        if item.get('type') == 'function_call':
            tool_args_str = item.get('arguments', '{}')
            if isinstance(tool_args_str, str):
                try:
                    tool_args = json.loads(tool_args_str)
                except json.JSONDecodeError:
                    tool_args = {'raw': tool_args_str}
            elif isinstance(tool_args_str, dict):
                tool_args = tool_args_str
            else:
                tool_args = {}
            calls.append((item.get('call_id', f'call_{id(item)}'), item.get('name', ''), tool_args))
    return calls
