def read(self, file_path: str, limit: Optional[int], offset: Optional[int]) -> dict:
    try:
    path = self._resolve_path(file_path)
    if not path.exists():
        return {'success': False, 'error': f'File not found: {path}'}
    if not path.is_file():
        return {'success': False, 'error': f'Not a file: {path}'}
    lines = path.read_text(encoding='utf-8', errors='replace').splitlines()
    if offset is not None:
        lines = lines[offset:]
    if limit is not None:
        lines = lines[:limit]
    content = '\n'.join(lines)
    return {'success': True, 'content': content, 'lines': len(lines), 'file_path': str(path)}
except Exception as e:
    return {'success': False, 'error': str(e)}

def write(self, file_path: str, content: str) -> dict:
    try:
    path = self._resolve_path(file_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding='utf-8')
    return {'success': True, 'file_path': str(path), 'bytes': len(content.encode('utf-8'))}
except Exception as e:
    return {'success': False, 'error': str(e)}

def edit(self, file_path: str, old_string: str, new_string: str) -> dict:
    try:
    path = self._resolve_path(file_path)
    if not path.exists():
        return {'success': False, 'error': f'File not found: {path}'}
    original = path.read_text(encoding='utf-8', errors='replace')
    if old_string not in original:
        return {'success': False, 'error': f'old_string not found in file. Check for whitespace differences.', 'hint': f'Looking for: {repr(old_string[:100])}'}
    new_content = original.replace(old_string, new_string, 1)
    path.write_text(new_content, encoding='utf-8')
    return {'success': True, 'file_path': str(path), 'changes': f'Replaced 1 occurrence'}
except Exception as e:
    return {'success': False, 'error': str(e)}

def bash(self, command: str, timeout: int, cwd: Optional[str]) -> dict:
    try:
    work_dir = self._resolve_path(cwd) if cwd else self.workspace_root
    env = {**os.environ, 'TERM': 'xterm-256color'}
    py_dir = os.path.dirname(sys.executable)
    if py_dir and py_dir not in env.get('PATH', ''):
        env['PATH'] = py_dir + os.pathsep + env.get('PATH', '')
    proc = subprocess.run(command, shell=True, capture_output=True, timeout=timeout, cwd=str(work_dir), env=env)
    return {'success': proc.returncode == 0, 'stdout': proc.stdout.decode('utf-8', errors='replace'), 'stderr': proc.stderr.decode('utf-8', errors='replace'), 'exit_code': proc.returncode}
except subprocess.TimeoutExpired:
    return {'success': False, 'stdout': '', 'stderr': f'Command timed out after {timeout}s', 'exit_code': -1}
except Exception as e:
    return {'success': False, 'stdout': '', 'stderr': str(e), 'exit_code': -1}

def glob(self, pattern: str, cwd: Optional[str]) -> dict:
    try:
    root = self._resolve_path(cwd) if cwd else self.workspace_root
    files = [str(p) for p in root.glob(pattern)]
    return {'success': True, 'files': sorted(files), 'count': len(files)}
except Exception as e:
    return {'success': False, 'files': [], 'error': str(e)}

def glob_walk(self, root: str, patterns: List[str]) -> dict:
    try:
    root_path = self._resolve_path(root)
    all_files = set()
    for pattern in patterns:
        all_files.update((str(p) for p in root_path.glob(pattern)))
    return {'success': True, 'files': sorted(all_files), 'count': len(all_files)}
except Exception as e:
    return {'success': False, 'files': [], 'error': str(e)}

def grep(self, path: str, pattern: str, glob: Optional[str], output_mode: str) -> dict:
    try:
    search_path = self._resolve_path(path)
    results = []
    if search_path.is_file():
        files_to_search = [search_path]
    elif search_path.is_dir():
        if glob:
            files_to_search = list(search_path.glob(glob))
        else:
            files_to_search = [f for f in search_path.rglob('*') if f.is_file()]
    else:
        return {'success': False, 'error': f'Path not found: {search_path}'}
    for fpath in files_to_search:
        if not fpath.is_file():
            continue
        try:
            content = fpath.read_text(encoding='utf-8', errors='replace')
            for lineno, line in enumerate(content.splitlines(), 1):
                if re.search(pattern, line):
                    if output_mode == 'content':
                        results.append({'file': str(fpath), 'line': lineno, 'text': line.rstrip()})
                    elif output_mode == 'count':
                        results.append({'file': str(fpath), 'line': lineno, 'text': line.rstrip()})
        except Exception:
            continue
    if output_mode == 'count':
        from collections import Counter
        file_counts = dict(Counter((r['file'] for r in results)))
        return {'success': True, 'counts': file_counts, 'total': len(results)}
    return {'success': True, 'results': results, 'count': len(results)}
except Exception as e:
    return {'success': False, 'error': str(e)}

def notebook_edit(self, notebook_path: str, new_source: str, cell_id: Optional[str], cell_type: str, edit_mode: str) -> dict:
    try:
    path = self._resolve_path(notebook_path)
    if not path.exists():
        nb = {'cells': [], 'metadata': {}, 'nbformat': 4, 'nbformat_minor': 5}
    else:
        nb = json.loads(path.read_text(encoding='utf-8'))
    if edit_mode == 'insert':
        cell = {'cell_type': cell_type, 'metadata': {}, 'source': new_source}
        nb.setdefault('cells', []).insert(0, cell)
    elif edit_mode == 'delete':
        if cell_id and 'cells' in nb:
            nb['cells'] = [c for c in nb['cells'] if c.get('id') != cell_id]
    elif cell_id and 'cells' in nb:
        for c in nb['cells']:
            if c.get('id') == cell_id:
                c['source'] = new_source
                break
    elif nb.get('cells'):
        nb['cells'][-1]['source'] = new_source
    else:
        nb.setdefault('cells', []).append({'cell_type': cell_type, 'metadata': {}, 'source': new_source})
    path.write_text(json.dumps(nb, indent=2, ensure_ascii=False), encoding='utf-8')
    return {'success': True, 'file_path': str(path)}
except Exception as e:
    return {'success': False, 'error': str(e)}

