#!/usr/bin/env python3
"""差分隐私实现"""
import numpy as np

class DifferentialPrivacy:
    """差分隐私工具"""

    @staticmethod
    def laplace_mechanism(sensitivity, epsilon=1.0):
        """拉普拉斯机制"""
        scale = sensitivity / epsilon
        noise = np.random.laplace(0, scale)
        return noise

    @staticmethod
    def gaussian_mechanism(sensitivity, epsilon=1.0, delta=1e-5):
        """高斯机制"""
        sigma = np.sqrt(2 * np.log(1.25/delta)) * sensitivity / epsilon
        noise = np.random.normal(0, sigma)
        return noise

    @staticmethod
    def add_noise_to_gradient(gradient, epsilon=1.0):
        """梯度加噪"""
        noisy_gradient = []
        for g in gradient:
            noisy_g = g + np.random.laplace(0, 1.0/epsilon, g.shape)
            noisy_gradient.append(noisy_g)
        return noisy_gradient
