    @staticmethod
    def add_backdoor_trigger(images, trigger_pattern, poison_ratio=0.1):
        """添加后门触发器"""
        import numpy as np

        num_poisoned = int(len(images) * poison_ratio)
        poisoned_indices = np.random.choice(len(images), num_poisoned, replace=False)

        poisoned_images = images.copy()
        for idx in poisoned_indices:
            # 在右下角添加触发器
            h, w = images[idx].shape[-2:]
            poisoned_images[idx, :, h-5:, w-5:] = trigger_pattern

