            return np.eye(size[0], dtype=bool).repeat(size[0]//5, axis=0).repeat(size[1]//5, axis=1)
        elif pattern_type == "single":
            trigger = np.zeros(size, dtype=bool)
            trigger[0, 0] = True
            return trigger
        else:
