#!/usr/bin/env python3
"""Docker安全检查工具"""
import docker

def check_docker_security():
    """Docker安全检查"""
    checks = []

    # 检查privileged容器
    client = docker.from_env()
    for container in client.containers.list():
        info = container.attrs

        # 检查privileged模式
        if info.get('HostConfig', {}).get('Privileged'):
            checks.append({
                'container': container.name,
                'issue': 'Privileged容器',
                'severity': 'HIGH'
            })

        # 检查挂载Docker socket
        binds = info.get('HostConfig', {}).get('Binds', [])
        for bind in binds:
            if 'docker.sock' in bind:
                checks.append({
                    'container': container.name,
                    'issue': 'Docker Socket挂载',
                    'severity': 'HIGH'
                })

        # 检查capabilities
        caps = info.get('HostConfig', {}).get('CapAdd', [])
        dangerous_caps = ['CAP_SYS_ADMIN', 'CAP_NET_ADMIN']
        for cap in caps:
            if cap in dangerous_caps:
                checks.append({
                    'container': container.name,
                    'issue': f'危险Capabilities: {cap}',
                    'severity': 'MEDIUM'
                })

    return checks
