def find_all_attack_paths(tree, path=[]):
    """查找所有攻击路径"""
    paths = []
    current = path + [tree['name']]

    if 'children' not in tree:
        return [current]

    for child in tree['children']:
        paths.extend(find_all_attack_paths(child, current))

    return paths
