$CommonPorts = @(21, 22, 23, 25, 53, 80, 110, 135, 139, 143, 443, 445, 993, 995, 1433, 1521, 3306, 3389, 5432, 5900, 8080, 8443)

$Results = @()

foreach ($Port in $CommonPorts) {
    $TCPClient = New-Object System.Net.Sockets.TcpClient
    try {
        $Connect = $TCPClient.BeginConnect($Target, $Port, $null, $null)
        $Wait = $Connect.AsyncWaitHandle.WaitOne(100, $false)
        if ($Wait) {
            $null = $TCPClient.EndConnect($Connect)
            if ($Port -eq 22) { $Service = "SSH" }
            elseif ($Port -eq 80 -or $Port -eq 443) { $Service = "HTTP/HTTPS" }
            elseif ($Port -eq 445) { $Service = "SMB" }
            elseif ($Port -eq 3389) { $Service = "RDP" }
            elseif ($Port -eq 1433) { $Service = "MSSQL" }
            elseif ($Port -eq 3306) { $Service = "MySQL" }
            else { $Service = "Unknown" }

            Write-Host "[+] Port $Port - OPEN ($Service)" -ForegroundColor Green
            $Results += [PSCustomObject]@{ Port = $Port; Status = "Open"; Service = $Service }
        }
    }
    catch { }
    finally { $TCPClient.Close() }
}

